<script setup lang="ts">import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';import {Head,useForm,usePage} from '@inertiajs/vue3';const props=defineProps<{students:any[],schoolYears:any[],gradeLevels:any[]}>();const page=usePage<any>();const preset=new URLSearchParams(location.search).get('student');const form=useForm({student_id:preset?Number(preset):props.students[0]?.id||'',school_year_id:props.schoolYears[0]?.id||'',grade_level_id:props.gradeLevels[0]?.id||'',enrollment_date:new Date().toISOString().slice(0,10),completion_date:'',status:'active'});</script>
<template><Head title="Add enrollment"/><AuthenticatedLayout><h1 class="h2">Add enrollment</h1><p class="text-secondary">Grade level belongs to this school-year enrollment, preserving the student’s history.</p><div v-if="!students.length||!schoolYears.length" class="alert alert-warning">Add an active student and a draft or active school year first.</div><div v-else class="card"><form class="card-body" @submit.prevent="form.post(route('enrollments.store'))"><div class="row g-3"><div class="col-md-6"><label class="form-label">Student</label><select v-model="form.student_id" class="form-select"><option v-for="s in students" :value="s.id">{{s.preferred_name||s.first_name}} {{s.last_name}}</option></select><div class="text-danger small">{{form.errors.student_id}}</div></div><div class="col-md-6"><label class="form-label">School year</label><select v-model="form.school_year_id" class="form-select"><option v-for="y in schoolYears" :value="y.id">{{y.name}}</option></select><div class="text-danger small">{{form.errors.school_year_id}}</div></div><div class="col-md-4"><label class="form-label">Grade level</label><select v-model="form.grade_level_id" class="form-select"><option v-for="g in gradeLevels" :value="g.id">{{g.name}}</option></select></div><div class="col-md-4"><label class="form-label">Enrollment date</label><input v-model="form.enrollment_date" type="date" class="form-control"></div><div class="col-md-4"><label class="form-label">Status</label><select v-model="form.status" class="form-select"><option>planned</option><option>active</option><option>completed</option><option>withdrawn</option><option>cancelled</option></select></div></div><button class="btn btn-primary mt-4" :disabled="form.processing">Save enrollment</button></form></div></AuthenticatedLayout></template>
